12	export function initGhostStoriesChannel(channel: Channel, options: Options) {
13	  /** Listens for events to discover and test stories */
14	  channel.on(GHOST_STORIES_REQUEST, async () => {
15	    const stats: {
16	      globMatchCount?: number;
17	      candidateAnalysisDuration?: number;
18	      totalRunDuration?: number;
19	      analyzedCount?: number;
20	      avgComplexity?: number;
21	      candidateCount?: number;
22	      testRunDuration?: number;
23	    } = {};
24	
25	    try {
26	      await telemetry('ghost-stories', async () => {
27	        try {
28	          const ghostRunStart = Date.now();
29	          const lastEvents = await getLastEvents();
30	          const lastInit = lastEvents?.init;
31	          const lastAISetup = lastEvents?.['ai-setup'];
32	          const lastGhostStoriesRun = lastEvents?.['ghost-stories'];
33	
34	          // We only want to run ghost stories immediately after init or ai setup.
35	          const lastRelevantEvent = lastAISetup ?? lastInit;
36	          if (!lastRelevantEvent) {
37	            throw new SkipGhostStoriesTelemetry();
38	          }
39	
40	          // Already ran once for this project — never run again
41	          if (lastGhostStoriesRun) {
42	            throw new SkipGhostStoriesTelemetry();
43	          }
44	
45	          // No session-ID match: `storybook ai setup` runs as a separate CLI
46	          // process, so its sessionId never matches the dev server's. The
47	          // `lastGhostStoriesRun` guard above is enough to enforce once-per-project.
48	
49	          const metadata = await getStorybookMetadata(options.configDir);
50	          const isReactStorybook = metadata?.renderer?.includes('@storybook/react');
51	          const hasVitestAddon =
52	            !!metadata?.addons &&
53	            Object.keys(metadata.addons).some((addonKey) =>
54	              addonKey.includes('@storybook/addon-vitest')
55	            );
56	
57	          // For now this is gated by React + Vitest
58	          if (!isReactStorybook || !hasVitestAddon) {
59	            throw new SkipGhostStoriesTelemetry();
60	          }
61	
62	          // Wait for any running tests to finish before launching scoring, so we don't
63	          // disturb end user activities.
64	          const isIdle = await waitForIdleVitest();
65	          if (!isIdle) {
66	            return;
67	          }
68	
69	          // Phase 1: find candidates from components
70	          const candidateAnalysisStart = Date.now();
71	          const candidatesResult = await getComponentCandidates();
72	          stats.candidateAnalysisDuration = Date.now() - candidateAnalysisStart;
73	          stats.globMatchCount = candidatesResult.globMatchCount;
74	          stats.analyzedCount = candidatesResult.analyzedCount ?? 0;
75	          stats.avgComplexity = candidatesResult.avgComplexity ?? 0;
76	          stats.candidateCount = candidatesResult.candidates.length;
77	
78	          if (candidatesResult.error) {
79	            stats.totalRunDuration = Date.now() - ghostRunStart;
80	            return {
81	              stats,
82	              runError: candidatesResult.error,
83	            };
84	          }
85	
86	          if (candidatesResult.candidates.length === 0) {
87	            stats.totalRunDuration = Date.now() - ghostRunStart;
88	            return {
89	              stats,
90	              runError: 'No candidates found',
91	            };
92	          }
93	
94	          // Phase 2: Run tests on those candidates Vitest. The components will be transformed directly to tests
95	          // If they pass, it means that creating a story file for them would succeed.
96	          const testRunResult = await runStoryTests(candidatesResult.candidates, {
97	            ghostRun: true,
98	          });
99	          stats.totalRunDuration = Date.now() - ghostRunStart;
100	          stats.testRunDuration = testRunResult.duration;
101	          if (testRunResult.runError) {
102	            return {
103	              stats,
104	              runError: testRunResult.runError,
105	            };
106	          }
107	
108	          return {
109	            stats,
110	            results: testRunResult.summary,
111	          };
112	        } catch (error) {
113	          if (error instanceof SkipGhostStoriesTelemetry) {
114	            throw error;
115	          }
116	
117	          return {
118	            stats,
119	            runError: 'Unknown error during ghost run',
120	          };
121	        }
122	      });
123	    } catch (error) {
124	      if (!(error instanceof SkipGhostStoriesTelemetry)) {
125	        throw error;
126	      }
127	    } finally {
128	      // we don't currently do anything with this, but will be useful in the future
129	      channel.emit(GHOST_STORIES_RESPONSE);
130	    }
131	  });
132	
133	  return channel;
134	}
